CREATE TABLE companies (id TEXT PRIMARY KEY,ticker TEXT UNIQUE NOT NULL,name_he TEXT NOT NULL,name_en TEXT,sector TEXT,subsector TEXT,is_active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE financial_periods (id TEXT PRIMARY KEY,company_id TEXT NOT NULL,fiscal_year INTEGER NOT NULL,fiscal_quarter INTEGER,period_type TEXT NOT NULL,period_start TEXT,period_end TEXT NOT NULL,report_date TEXT,currency TEXT NOT NULL DEFAULT 'ILS',unit TEXT NOT NULL DEFAULT 'MILLIONS',audited INTEGER NOT NULL DEFAULT 0,data_status TEXT NOT NULL,source_ids_json TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(company_id) REFERENCES companies(id));
CREATE TABLE financial_statements (period_id TEXT PRIMARY KEY,company_id TEXT NOT NULL,revenue REAL,cost_of_revenue REAL,gross_profit REAL,operating_expenses REAL,operating_income REAL,depreciation_and_amortization REAL,ebitda_reported REAL,ebitda_ex_ifrs16 REAL,finance_income REAL,finance_expense REAL,profit_before_tax REAL,income_tax_expense REAL,net_income REAL,net_income_attributable_to_owners REAL,eps_basic REAL,eps_diluted REAL,cash_and_cash_equivalents REAL,short_term_investments REAL,trade_receivables REAL,other_receivables REAL,inventory REAL,current_assets REAL,property_plant_equipment REAL,right_of_use_assets REAL,intangible_assets REAL,total_assets REAL,short_term_debt REAL,long_term_debt REAL,lease_liabilities_current REAL,lease_liabilities_non_current REAL,trade_payables REAL,other_payables REAL,current_liabilities REAL,total_liabilities REAL,equity REAL,equity_attributable_to_owners REAL,cash_flow_from_operations REAL,capex REAL,acquisitions REAL,dividends_paid REAL,interest_paid REAL,taxes_paid REAL,lease_principal_payments REAL,lease_interest_payments REAL,total_lease_cash_payments REAL,proceeds_from_debt REAL,debt_repayments REAL,share_repurchases REAL,FOREIGN KEY(period_id) REFERENCES financial_periods(id));
CREATE TABLE financial_sources (id TEXT PRIMARY KEY,company_id TEXT NOT NULL,title TEXT NOT NULL,source_type TEXT NOT NULL,url TEXT,publication_date TEXT,report_period_end TEXT,retrieved_at TEXT NOT NULL,notes TEXT,created_at TEXT NOT NULL);
CREATE TABLE market_snapshots (id TEXT PRIMARY KEY,company_id TEXT NOT NULL,snapshot_date TEXT NOT NULL,share_price REAL,shares_outstanding REAL,market_cap REAL,enterprise_value REAL,source_id TEXT,data_status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE validation_results (id TEXT PRIMARY KEY,company_id TEXT NOT NULL,period_id TEXT,severity TEXT NOT NULL,code TEXT NOT NULL,message TEXT NOT NULL,created_at TEXT NOT NULL);
